  sky: Object.assign(theme(PAL.purple, { mover: PAL.blue, spring: PAL.blue, rubber: PAL.blue, crumble: PAL.white }), { dots: PAL.gray, glass: true, hazard: 'storm', wallHaz: 'lightning' }),   // the Skyscraper (see SKY), the TV
