    ln(Wd - 0.6 + lean, eave + 0.5, Wd - 0.5 + lean, top + 0.5, G, 5); for (let i = 0; i < 3; i++) F(X(Wd - 0.5 + lean + 0.15 * Math.sin(T + i)), Y(top + 0.85 + 0.4 * i), (0.18 + 0.05 * i) * t, 0, 0, 0.12 * t, G, DIM, 4);   // a smoking chimney
